// header pointer, its copy ctor and dtor are inline forwarders into the
// out-of-line StringBase<char> bodies, and str() returns the character run that
// starts 8 bytes into that header.
template <typename T> struct BfmeComboStringData
{
	int m_refCount;
	int m_length;
	T m_text[1];
};

template <typename T> class BfmeComboStringBase
{
