private:
	BfmeComboStringBase() : m_data(0) {}
	BfmeComboStringBase(const T *text);
	BfmeComboStringBase(const BfmeComboStringBase<T> &other);
	~BfmeComboStringBase();

	BfmeComboStringData<T> *m_data;
};

class AsciiString : private BfmeComboStringBase<char>
{
public:
	AsciiString() : BfmeComboStringBase<char>() {}
	AsciiString(const char *text) : BfmeComboStringBase<char>(text) {}
	AsciiString(const AsciiString &other) : BfmeComboStringBase<char>(other) {}
	~AsciiString() {}

	// pinned ??4AsciiString@@QAEAAV0@PBD@Z (retail ILT 0x00028BB9)
	void set(const char *s);

	const char *str(void) const
	{
		return m_data ? m_data->m_text : "";
	}
};

